package br.com.weg.workshop.workshop.dto;
import br.com.weg.workshop.workshop.domain.Workshop; import java.math.BigDecimal; import java.time.*; import java.util.UUID;
public record WorkshopResponse(UUID id,String title,String description,String image,UUID themeId,UUID categoryId,LocalDate startDate,LocalDate endDate,LocalTime startTime,LocalTime endTime,String location,String modality,BigDecimal price,Instant registrationStart,Instant registrationEnd,int maximumParticipants,String paymentMethod,boolean championship,String additionalInformation,String status,Instant scheduledPublishAt,Instant publishedAt,UUID createdBy) { public static WorkshopResponse from(Workshop w){return new WorkshopResponse(w.getId(),w.getTitle(),w.getDescription(),w.getImage(),w.getTheme().getId(),w.getCategory().getId(),w.getStartDate(),w.getEndDate(),w.getStartTime(),w.getEndTime(),w.getLocation(),w.getModality().name(),w.getPrice(),w.getRegistrationStart(),w.getRegistrationEnd(),w.getMaximumParticipants(),w.getPaymentMethod().name(),w.isChampionship(),w.getAdditionalInformation(),w.getStatus().name(),w.getScheduledPublishAt(),w.getPublishedAt(),w.getCreatedBy().getId());} }
